export const code = async (inputs) => {
  let rows = [];
  const raw = inputs.trips;
  if (Array.isArray(raw)) {
    rows = raw;
  } else if (raw && typeof raw === 'object') {
    const objVals = Object.values(raw);
    if (objVals.length > 0 && objVals[0] && typeof objVals[0] === 'object' && (objVals[0] as any).values) {
      rows = objVals;
    } else {
      rows = raw.data || raw.rows || objVals;
      if (!Array.isArray(rows)) rows = [rows];
    }
  }

  const trips = rows.map((r) => {
    const row = r as any;
    const v = (row && row.values) ? row.values : (row || {});
    // Trips sheet: A=Trip_ID, B=User_ID, C=Trip_Name, D=Source, E=Destination, F=Start_Date, G=End_Date, H=Purpose, I=Budget, J=Status
    return {
      trip_id:   String(v.A || row.Trip_ID || row.trip_id || '').trim(),
      user_id:   String(v.B || row.User_ID || row.user_id || '').trim(),
      trip_name: String(v.C || row.Trip_Name || row.trip_name || '').trim(),
      source:    String(v.D || row.Source || row.source || '').trim(),
      destination: String(v.E || row.Destination || row.destination || '').trim(),
      start_date: String(v.F || row.Start_Date || row.start_date || '').trim(),
      end_date:   String(v.G || row.End_Date || row.end_date || '').trim(),
      purpose:    String(v.H || row.Purpose || row.purpose || '').trim(),
      budget:     parseFloat(v.I || row.Budget || row.budget || 0),
      status:     String(v.J || row.Status || row.status || 'Active').trim()
    };
  });

  const response = { success: true, trips: trips };
  return { response_body: JSON.stringify(response) };
};
